using Ohno.CircleGame.Gameplay;
namespace Ohno.QA12;
public static partial class Tests
{
    static void Frequency()
    {
        foreach(var (r,bits) in new (float,uint)[]{(0,0x469c4000),(.5f,0x471c4000),(1,0x476a6000),(2,0x47c35000),(3,0x47c35000),(-1,0xc69c4000),(.000024999997f,0x469c4000),(.000025f,0x469c4200),(-.000025f,0x469c3e00),(53687.0875f,0xceffff66),(-53687.09f,0xceffff64)})
            Add("F01 ratio "+r,"E041 M3b28;independent IEEE32 literal oracle",()=>{var f=new Rig();f.Spin.Modulate(r);Seq(f.B.Ops.Select(o=>o.Name),"Length","Attribute");Eq(f.B.Ops[0].Handle,733);Eq(f.B.Ops[0].Attr,0);Eq(f.B.Ops[1].Attr,1);Bits(f.B.Ops[1].Value,bits);f.Trace();});
        foreach(long length in new[]{long.MinValue,-8193L,-1L,0L,8191L,8192L,8193L,long.MaxValue})Add("F02 signed length "+length,"E041 signed Int64 strict8192 boundary",()=>{var f=new Rig();f.B.Query=(_,_)=>length;f.Spin.Modulate(.5f);Eq(f.B.Ops.Count,length>8192?2:1);if(length>8192)Bits(f.B.Ops[1].Value,0x471c4000);else Eq(f.Spin.RequestedFrequency,null);f.Trace();});
        foreach(int handle in new[]{-987,-1,0,733})foreach(int activity in new[]{0,1})Add($"F03 handle{handle} activity{activity}","E041 M3b28 lacks activity/validity gate",()=>{var f=new Rig();f.Spin.Channel=handle;f.B.States[handle]=activity;f.Spin.Modulate(1);Seq(f.B.Ops.Select(o=>o.Handle),handle,handle);Yes(!f.B.Ops.Any(o=>o.Name=="Activity"),"no activity query");Bits(f.B.Ops[1].Value,0x476a6000);});
        Add("F04 replacement during Length","E041 M3b28 separate F2356 reads0000/0012",()=>{var f=new Rig();f.B.Query=(h,m)=>{Eq(h,733);Eq(m,0);f.Spin.Channel=929;return 8193;};f.Spin.Modulate(.5f);Seq(f.B.Ops.Select(o=>o.Handle),733,929);});
        foreach(float ratio in new[]{float.NaN,float.PositiveInfinity,float.NegativeInfinity,float.MaxValue,53687.09375f,-53687.09765625f})Add("F05 unpinned conversion "+ratio,"ENGINEERING unsupported;original exceptional conv.i4 symbolic",()=>{var f=new Rig();f.Spin.Modulate(ratio);Eq(f.Spin.FrequencyStatus,FrequencyCapability.Unsupported);Eq(f.Spin.RequestedFrequency,null);Seq(f.B.Ops.Select(o=>o.Name),"Length");Yes(f.Spin.FrequencyError is not null,"unsupported reason");});
        Add("F06 missing length capability keeps continuing eligible","ENGINEERING no byte-length substitution",()=>{var f=new Rig();f.B.Query=(_,_)=>null;f.Spin.Continue(.5f);Eq(f.Global.Pending,1);Eq(f.Spin.FrequencyStatus,FrequencyCapability.Unsupported);f.Global.Drain();Seq(f.B.Ops.Select(o=>o.Name),"Length","Attribute","Play");Eq(f.B.Ops[^1].Flag,false);});
        foreach(var status in new[]{FrequencyCapability.Unsupported,FrequencyCapability.Failed})Add("F07 backend capability "+status,"ENGINEERING capability never silently attr1 success",()=>{var f=new Rig();f.B.FrequencyCapability=status;f.Spin.Modulate(.5f);Eq(f.Spin.FrequencyStatus,FrequencyCapability.Unsupported);Eq(f.Spin.RequestedFrequency,40000f);Seq(f.B.Ops.Select(o=>o.Name),"Length");});
        foreach(string op in new[]{"Length","Attribute"})Add("F08 backend failure "+op,"E041 model propagation;status Failed engineering",()=>{var f=new Rig();f.B.Enter=o=>{if(o.Name==op)throw new IOException(op);};Throws<IOException>(()=>f.Spin.Continue(.5f));Eq(f.Global.Pending,0);Eq(f.Spin.FrequencyStatus,FrequencyCapability.Failed);Eq(f.Spin.FrequencyError,op);});
        Add("F09 recovered capability after failure","ENGINEERING observable recovery",()=>{var f=new Rig();f.B.Query=(_,_)=>null;f.Spin.Modulate(.5f);f.B.Query=(_,_)=>8193;f.Spin.Modulate(1);Eq(f.Spin.FrequencyStatus,FrequencyCapability.Supported);Eq(f.Spin.FrequencyError,null);});
    }
    static void Observations()
    {
        Add("O01 first change C before frequency raw0 and late cache","E025/E041 M05f6:02ed/030d/04c7",()=>{var f=new Rig();var o=new SpinnerProgressObservation();int raw=o.Observe(19,20,()=>{Eq(o.Count,1);Eq(o.CachedInteger,0);f.Spin.Observe(o.Count,20,true);},()=>throw new Exception("unexpected bonus"));Eq(raw,0);Eq(o.CachedInteger,19);Bits(f.B.Ops[^1].Value,0x46abe000);});
        Add("O02 unchanged converted P has no callback","E025 integer inequality",()=>{var o=new SpinnerProgressObservation();o.Observe(2,20);int calls=0;Eq(o.Observe(2.99f,20,()=>calls++),0);Eq(calls,0);Eq(o.Count,1);Eq(o.CachedInteger,2);});
        Add("O03 jump increments once each direction","E025 inequality not crossed-integer count",()=>{var o=new SpinnerProgressObservation();Eq(o.Observe(77,20),0);Eq(o.Observe(-19,20),8192);Eq(o.Count,2);Eq(o.CachedInteger,-19);});
        foreach(bool enabled in new[]{false,true})Add("O04 frequency enabled "+enabled,"E041 setting observation only",()=>{var f=new Rig();var o=new SpinnerProgressObservation();Eq(o.Observe(7,20,()=>f.Spin.Observe(o.Count,20,enabled)),0);Eq(f.B.Ops.Count,enabled?2:0);Eq(o.Count,1);});
        Add("O05 frequency before classification and bonus before cache","E041 M05f6 optional frequency precedes fresh selector",()=>{var f=new Rig();var o=new SpinnerProgressObservation();for(int i=1;i<=24;i++)o.Observe(i,20);var order=new List<string>();int raw=o.Observe(25,20,()=>{order.Add("changed");Eq(o.Count,25);Eq(o.CachedInteger,24);f.Spin.Observe(o.Count,20,true);order.Add("frequency");},()=>{order.Add("bonus");Eq(o.CachedInteger,24);Eq(f.B.Ops[^1].Value,70000f);});Eq(raw,16384);Seq(order,"changed","frequency","bonus");Eq(o.CachedInteger,25);});
        Add("O06 pure change exception preserves C stale cache","E041 original partial helper boundary",()=>{var o=new SpinnerProgressObservation();Throws<IOException>(()=>o.Observe(1,20,()=>throw new IOException("changed")));Eq(o.Count,1);Eq(o.CachedInteger,0);Eq(o.Observe(1,20),8192);Eq(o.Count,2);});
        Add("O07 pure bonus exception retains C and stale cache","E041 bonus before cache store",()=>{var o=new SpinnerProgressObservation();for(int i=1;i<=24;i++)o.Observe(i,20);Throws<IOException>(()=>o.Observe(25,20,bonus:()=>throw new IOException("bonus")));Eq(o.Count,25);Eq(o.CachedInteger,24);});
        Add("O08 state callback failure contained before progress handoff","R14 ENGINEERING containment versus pure model propagation",()=>{var s=State();s.Observation.Observe(1,s.Required);s.Sound+=(_,_)=>throw new IOException("optional effect");Eq(s.SampleAngle(0,2300,20,true),8192);Eq(s.Observation.Count,2);Eq(s.Observation.CachedInteger,0);Yes(s.SoundError!.Contains("optional effect"),"contained error visible");});
        Add("O09 fresh ratio count and required","E041 fresh C/N Single operands",()=>{var f=new Rig();f.Spin.Observe(3,4,true);Eq(f.Spin.LastRatio,.75f);Eq(f.Spin.RequestedFrequency,50000f);f.Spin.Observe(1,8,true);Eq(f.Spin.RequestedFrequency,25000f);});
    }
}
